// Este nó recebe os dados consolidados do Analista de Perfil e monta os textos de e-mail
const itens = $input.all();
const resultados = [];

for (const item of itens) {
  const dados = item.json;
  const nome = dados.nome || "Cliente";
  const email = dados.email || "Sem e-mail";
  const saldo = dados.saldo || "R$ 0,00";
  const perfil = dados.perfil || "Não definido";
  const produtos = dados.produtos_elegiveis || [];

  // Seleciona até 3 produtos recomendados
  const topTresProdutos = produtos.slice(0, 3);

  // Monta a estrutura da mensagem com as recomendações de investimento
  let corpoMensagem = `Olá, equipe!\n\nSegue a análise de recomendação do cliente:\n`;
  corpoMensagem += `• Nome: ${nome}\n`;
  corpoMensagem += `• E-mail: ${email}\n`;
  corpoMensagem += `• Saldo Disponível: ${saldo}\n`;
  corpoMensagem += `• Perfil do Investidor: ${perfil}\n\n`;

  if (topTresProdutos.length > 0) {
    corpoMensagem += `Opções recomendadas (Até 3 produtos compatíveis):\n`;
    topTresProdutos.forEach((prod, index) => {
      corpoMensagem += `${index + 1}. Produto: ${prod.produto} | Mínimo: R$ ${prod.minimo} | Rentabilidade: ${prod.rentabilidade}\n`;
    });
  } else {
    corpoMensagem += `Não foram encontrados produtos compatíveis com o saldo de investimento mínimo e perfil deste cliente no momento.\n`;
  }

  resultados.push({
    json: {
      destinatario_equipe: "equipe-vendas@suaempresa.com",
      assunto_email: `Recomendações de Investimento - ${nome} (${perfil})`,
      conteudo_mensagem: corpoMensagem,
      cliente_nome: nome,
      cliente_email: email,
      cliente_saldo: saldo,
      cliente_perfil: perfil
    }
  });
}

return resultados;

// 1. Processa o CSV vindo do HTTP Request (dados de investimentos)
const csvData = $input.first().json.data || '';
const linhasCsv = csvData.trim().split('\n');
linhasCsv.shift(); // Remove o cabeçalho

const matrizInvestimentos = linhasCsv.map(linha => {
  const colunas = linha.split(',');
  return {
    perfil: colunas[0]?.trim(),
    produto: colunas[1]?.trim(),
    minimo: Number(colunas[2]?.trim()) || 0,
    rentabilidade: colunas[3]?.trim()
  };
});

// 2. Resgata a lista de clientes que veio dentro do payload único do Webhook
const webhookData = $('Webhook').first().json.body;
const listaClientes = webhookData.clientes || [];

// 3. Itera sobre cada cliente e gera um item de output para cada um deles
return listaClientes.map(cliente => {
  const nome = cliente.nome || 'Cliente';
  const email = cliente.email || '';
  const perfil = cliente.perfil || 'Conservador';

  // Tratamento do saldo
  let saldoBruto = cliente.saldo;
  let saldoLimpo = 0;

  if (typeof saldoBruto === 'number') {
    saldoLimpo = saldoBruto;
  } else if (typeof saldoBruto === 'string') {
    saldoLimpo = Number(saldoBruto.replace('R$', '').replace(/\\./g, '').replace(',', '.').trim()) || 0;
  }

  // Filtra as opções de investimento compatíveis com o perfil e saldo do cliente
  const produtosRecomendados = matrizInvestimentos.filter(opcao => 
    opcao.perfil.toLowerCase() === perfil.toLowerCase() && saldoLimpo >= opcao.minimo
  );

  return {
    json: {
      nome: nome,
      email: email,
      saldo: saldoBruto,
      perfil: perfil,
      produtos_elegiveis: produtosRecomendados
    }
  };
});
